def paths(g):
    h,w=len(g),len(g[0])
    cells={(r,c) for r in range(h) for c in range(w) if g[r][c]==3}
    def nb(p): return [q for q in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if q in cells]
    rem=set(cells); res=[]
    while rem:
        start=None
        for p in rem:
            if len([q for q in nb(p) if q in rem])==1: start=p;break
        if start is None: start=next(iter(rem))
        path=[start]; rem.discard(start)
        while True:
            nxt=[q for q in nb(path[-1]) if q in rem]
            if not nxt: break
            rem.discard(nxt[0]); path.append(nxt[0])
        res.append(path)
    return res
