def transform(g):
    H=len(g); W=len(g[0])
    seed=[(r,c) for r in range(H) for c in range(W) if g[r][c]==3]
    if not seed: return [row[:] for row in g]
    sr,sc=seed[0]
    # arms: outward from seed: U2,R2,D4,L4,U6,R6,D8,L8,U10,R12,D12,L14,U14,...
    cells=[]; r,c=sr,sc
    def go(dr,dc,n):
        nonlocal r,c
        for _ in range(n):
            r+=dr; c+=dc
            if 0<=r<H and 0<=c<W: cells.append((r,c))
    seq=[(-1,0,2),(0,1,2),(1,0,4),(0,-1,4),(-1,0,6),(0,1,6),(1,0,8),(0,-1,8),
         (-1,0,10),(0,1,12),(1,0,12),(0,-1,14),(-1,0,14),(0,1,16),(1,0,16),(0,-1,18)]
    for dr,dc,n in seq: go(dr,dc,n)
    tmpl=set(cells)|{(sr,sc)}
    # delete 2s in seed row (not on template they'd be redrawn by pen anyway)
    keep2={(r,c) for r in range(H) for c in range(W) if g[r][c]==2 and r!=sr}
    # pen from seed along template order (cells list is outward order); stop at 2
    drawn={(sr,sc)}
    for cell in cells:
        if cell in keep2: break
        drawn.add(cell)
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if (r,c) in drawn: out[r][c]=3
            elif (r,c) in keep2: out[r][c]=2
            else: out[r][c]=0
    return out

